// import 'jasmine'; (google3-only)
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-carousel.js';
import './md-gb-carousel-item.js';

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

/** Waits for Lit updates and a frame. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  await new Promise((resolve) => requestAnimationFrame(resolve));
}

// Announcer contract: no live region to read in this component.

describe('<md-gb-carousel> announcer contract (AnnouncerController)', () => {
  afterEach(() => container?.remove());

  it('is a list of labelled items, so assistive technology reads the item in focus and the total', async () => {
    // spec: carousel-2fcc15, carousel-e273a7
    const root = await mount(html`
      <button id="before">Before</button>
      <md-gb-carousel aria-label="Destinations" style="inline-size: 360px; --item-width: 186px; --height: 200px">
        <md-gb-carousel-item label="Item 1"><span slot="label">One</span></md-gb-carousel-item>
        <md-gb-carousel-item label="Item 2"><span slot="label">Two</span></md-gb-carousel-item>
        <md-gb-carousel-item label="Item 3"><span slot="label">Three</span></md-gb-carousel-item>
      </md-gb-carousel>
    `);
    const el = root.querySelector<any>('md-gb-carousel')!;
    const before = root.querySelector<HTMLElement>('#before')!;
    before.focus();
    await settle();
    const scroller = el.shadowRoot.querySelector('[part="scroller"]') as HTMLElement;
    expect(scroller.getAttribute('role')).toBe('list');
    const items = [...el.querySelectorAll('md-gb-carousel-item')] as HTMLElement[];
    expect(items.length).toBe(3);
    for (const [i, item] of items.entries()) {
      expect((item as any).internals.role).toBe('listitem');
      const action = item.shadowRoot!.querySelector('.carousel-item-action')!;
      expect(action.getAttribute('aria-label')).toBe('Item ' + (i + 1));
    }
  });
});
